CAT = "phnleSurgOxy"; SEG = "NP3"
# Nursing Practice III: care of clients with problems in surgery, oxygenation, fluid and
# electrolytes, infectious, inflammatory and immunologic response, and cellular aberrations.
# 40 items, 10 per test.
Q = [
# Perioperative
("The evening before elective abdominal surgery, which nursing action has the highest priority?",
 "Confirm the signed consent", ["Shave the whole abdomen", "Serve a large dinner", "Start teaching a new diet"],
 "A valid signed consent must be in the chart before any premedication. Shaving is avoided or done with clippers just before surgery."),
("Why are dentures removed before a patient goes to the operating room under general anesthesia?",
 "They can block the airway", ["They harbor surgical site bacteria", "They interfere with the cautery", "They raise the blood pressure"],
 "Loose dentures can fall back and obstruct the airway during intubation or emergence from anesthesia."),
("Which member of the surgical team counts sponges, needles and instruments with the scrub nurse?",
 "The circulating nurse", ["The anesthesiologist", "The assisting surgeon", "The recovery room nurse"],
 "The scrub and circulating nurses count together before incision, before closure and at skin closure, and record the counts."),
("Which action breaks the sterile field during surgery?",
 "Reaching across the sterile field", ["Keeping hands above the waist", "Facing the sterile field", "Passing gown to gown"],
 "Unsterile persons must not reach over a sterile field. Sterile items are kept above waist level and within view."),
("A postoperative patient in the recovery room is drowsy and snoring loudly. The first nursing action is to:",
 "Tilt the head and lift the jaw", ["Give the ordered analgesic", "Raise the side rails", "Check the incision dressing"],
 "Snoring signals partial airway obstruction by the tongue. Airway comes first, before pain relief or wound checks."),
("On the second postoperative day a patient coughs and feels something give way at the incision, and loops of bowel are visible. The nurse first:",
 "Covers it with moist sterile gauze", ["Pushes the bowel back in", "Has her walk to the bathroom", "Applies a dry pressure dressing"],
 "Evisceration is covered with sterile gauze moistened with saline, the patient is placed in low Fowler's with knees bent, and the surgeon is called."),
("Which exercise helps prevent deep vein thrombosis after surgery?",
 "Ankle pumps every hour", ["Bed rest with knees flexed", "Massaging the calves", "A pillow under the knees"],
 "Ankle pumps and early ambulation keep venous blood moving. Calf massage could dislodge a clot; pillows under the knees slow venous return."),
("A patient is taught to use an incentive spirometer after surgery. Its main purpose is to:",
 "Prevent atelectasis", ["Strengthen leg muscles", "Measure blood oxygen", "Relieve incision pain"],
 "Slow, deep breaths held at the top expand the alveoli and prevent the collapse that leads to pneumonia."),
# Oxygenation
("A patient with chronic obstructive pulmonary disease is short of breath. Which oxygen flow is usually ordered first?",
 "1 to 2 L/min by nasal cannula", ["10 L/min by simple face mask", "15 L/min by nonrebreather", "6 to 8 L/min by cannula"],
 "Low-flow oxygen avoids blunting the hypoxic drive and worsening carbon dioxide retention in some COPD patients; the flow is titrated to the target saturation."),
("The nurse teaches pursed-lip breathing to a patient with emphysema. It helps by:",
 "Keeping the airways open longer", ["Increasing the respiratory rate", "Loosening thick secretions", "Strengthening the diaphragm only"],
 "Exhaling through pursed lips creates back pressure that splints the small airways open and lets trapped air out."),
("Arterial blood gases show pH 7.30, PaCO2 55 mmHg and HCO3 25 mEq/L. This is:",
 "Respiratory acidosis", ["Metabolic acidosis", "Respiratory alkalosis", "Metabolic alkalosis"],
 "Low pH with high PaCO2 and a normal bicarbonate is uncompensated respiratory acidosis, as in hypoventilation."),
("A patient's chest tube comes apart from the drainage tubing. The nurse first:",
 "Puts the tube end in sterile water", ["Clamps the tube for an hour", "Pulls the chest tube out", "Raises the drainage unit"],
 "Placing the end under sterile water makes a temporary water seal so air cannot enter the chest. Prolonged clamping risks tension pneumothorax."),
("Each pass of the catheter when suctioning an adult's airway should last no longer than:",
 "10 to 15 seconds", ["30 to 45 seconds", "1 minute", "3 to 5 seconds"],
 "Longer passes remove oxygen and can cause hypoxia and bradycardia. Suction is applied only while withdrawing the catheter."),
("A patient with asthma starts an inhaled corticosteroid. What should the nurse teach?",
 "Rinse the mouth after each use", ["Use it during an attack", "Stop it when symptoms ease", "Swallow the rinse water"],
 "Rinsing removes drug from the mouth and prevents oral candidiasis. Inhaled steroids control inflammation; they do not relieve an attack."),
# Fluids and electrolytes
("A patient has a serum potassium of 6.2 mEq/L. Which finding is the nurse most concerned about?",
 "Tall, peaked T waves", ["Leg cramps at night", "A dry mouth", "A mild frontal headache"],
 "Hyperkalemia can cause dangerous dysrhythmias; peaked T waves are an early ECG sign that needs urgent treatment."),
("Before adding potassium chloride to an IV infusion, the nurse first checks the patient's:",
 "Urine output", ["Skin turgor", "Pupil size", "Bowel sounds"],
 "Potassium is excreted by the kidneys; giving it with poor urine output can cause hyperkalemia. It is never given as an IV push."),
("A patient with a serum sodium of 125 mEq/L becomes confused. Which IV fluid is hypotonic and should be avoided?",
 "0.45% sodium chloride", ["0.9% sodium chloride", "Lactated Ringer's", "3% sodium chloride"],
 "Half-normal saline would lower the sodium further and worsen cerebral edema. Severe symptomatic hyponatremia may be treated with hypertonic saline as ordered."),
("A positive Trousseau's sign, carpal spasm when a blood pressure cuff is inflated, suggests:",
 "Hypocalcemia", ["Hypercalcemia", "Hyperkalemia", "Hypernatremia"],
 "Low calcium increases nerve excitability, causing Trousseau's and Chvostek's signs and tetany. It can follow thyroid or parathyroid surgery."),
("An IV site is cool, pale and swollen, and the infusion has slowed. The nurse suspects:",
 "Infiltration", ["Phlebitis", "Air embolism", "Circulatory overload"],
 "Fluid leaking into tissue makes the site cool, pale and puffy. Phlebitis causes warmth, redness and a tender vein."),
("A liter of IV fluid is ordered over 8 hours with a set that delivers 15 drops/mL. What is the drip rate?",
 "31 drops per minute", ["21 drops per minute", "47 drops per minute", "125 drops per minute"],
 "1,000 mL / 480 min x 15 drops/mL = 31.25, so 31 drops per minute. 125 is the rate in mL per hour."),
# Infectious and immunologic
("A patient with suspected pulmonary tuberculosis is admitted. Which precaution is used?",
 "Airborne precautions", ["Contact precautions", "Droplet precautions", "Standard precautions only"],
 "TB spreads by droplet nuclei that stay in the air; a negative-pressure room and an N95 respirator are used."),
("A patient on anti-TB drugs reports orange-red urine. The nurse explains that this is caused by:",
 "Rifampicin", ["Isoniazid", "Pyrazinamide", "Ethambutol"],
 "Rifampicin colors urine, sweat and tears orange-red; it is harmless. Isoniazid can cause neuropathy, prevented with vitamin B6."),
("A patient on ethambutol should report which change at once?",
 "Changed color vision", ["Orange-red urine", "Joint pain", "Mild nausea after doses"],
 "Ethambutol can cause optic neuritis; vision and color discrimination are checked. Joint pain is linked with pyrazinamide."),
("A farmer with fever, calf muscle pain and red eyes after wading through floodwater most likely has:",
 "Leptospirosis", ["Typhoid fever", "Dengue fever", "Malaria"],
 "Leptospira from rat urine enters through skin during floods. Calf pain and conjunctival suffusion are classic signs."),
("A patient with typhoid fever should be watched for which serious complication in the second or third week?",
 "Intestinal perforation", ["Optic neuritis", "Orchitis", "Rheumatic heart disease"],
 "Salmonella Typhi ulcerates Peyer's patches; sudden abdominal pain and rigidity in the later weeks suggest perforation."),
("A patient develops wheezing, hives and a falling blood pressure minutes after an IV antibiotic starts. The first drug given is:",
 "Epinephrine", ["Diphenhydramine", "Hydrocortisone", "Salbutamol"],
 "Anaphylaxis is treated first with intramuscular epinephrine after stopping the drug. Antihistamines and steroids are adjuncts."),
("A patient with systemic lupus erythematosus should be taught to avoid:",
 "Prolonged sun exposure", ["Daily fluid intake", "Gentle exercise", "Planned rest periods each day"],
 "Ultraviolet light can trigger rashes and disease flares; sunscreen and covering clothing are advised."),
("Which hand hygiene practice best prevents health care-associated infection?",
 "Hand hygiene at each contact", ["Gloves instead of hand hygiene", "Washing hands only when soiled", "Hand rub once per shift"],
 "Hand hygiene at the WHO moments, before and after contact and procedures, is the single most effective measure. Gloves do not replace it."),
("Under the HIV and AIDS Policy Act (R.A. 11166), HIV testing of a patient generally requires:",
 "Informed consent", ["A court order", "A spouse's permission", "Approval of the barangay"],
 "R.A. 11166 makes HIV testing voluntary with informed consent and protects the confidentiality of the result, with narrow exceptions in the law."),
("A patient with hepatitis A is admitted. Which precaution is added to standard precautions for an incontinent patient?",
 "Contact precautions", ["Airborne precautions", "Reverse isolation", "Droplet precautions"],
 "Hepatitis A spreads by the fecal-oral route; contact precautions apply when the patient is diapered or incontinent."),
# Cellular aberrations
("A patient receiving chemotherapy has a white cell count of 1,200/mm3. Which visitor should be kept from the room?",
 "A grandchild with a cold", ["A spouse who is well", "A pastor who is well", "A son with a sprained ankle"],
 "Neutropenic patients are protected from anyone with an infection. Fresh flowers and raw fruits are also usually avoided."),
("A patient on chemotherapy has a platelet count of 30,000/mm3. Which instruction is right?",
 "Use a soft toothbrush", ["Floss vigorously", "Take aspirin for pain", "Shave with a razor"],
 "Thrombocytopenia raises bleeding risk: soft brushes, electric razors and no aspirin or intramuscular injections."),
("What does the nurse teach a patient about skin in an external radiation field?",
 "Wash gently with water", ["Apply a heating pad", "Scrub off the ink markings", "Use perfumed lotion"],
 "Field markings stay on; the skin is washed gently and kept from heat, sun and scented products unless the team approves."),
("Which change is one of the warning signs of cancer?",
 "A sore that does not heal", ["A cough with a fever", "Brief muscle soreness", "A single mild headache in the morning"],
 "The CAUTION signs include a sore that does not heal, change in bowel or bladder habits, unusual bleeding, a lump, indigestion, change in a wart and nagging cough."),
("A woman asks when to do breast self-examination each month. The nurse advises:",
 "A week after menses begin", ["On the first day of menses", "Just before menses begin", "Only when a lump is felt"],
 "About 7 days after the start of the period the breasts are least tender and swollen, so lumps are easier to find."),
("A patient taking a vesicant chemotherapy drug complains of burning at the IV site. The nurse first:",
 "Stops the infusion", ["Slows the infusion rate", "Applies a warm compress", "Flushes the line hard"],
 "Possible extravasation of a vesicant: stop the drug at once, leave the cannula in to aspirate as protocol directs, and notify the physician."),
("Which food is best for a patient with mouth sores from chemotherapy?",
 "Cool, soft gelatin", ["Spicy adobo", "Hot sinigang soup", "Toasted crackers with salt"],
 "Cool, soft, bland foods soothe stomatitis. Spicy, acidic, hot or rough foods irritate the mucosa."),
("A patient with cancer pain uses oral morphine on a schedule. Which side effect should the nurse prevent?",
 "Constipation", ["Diarrhea", "Hypertension", "Insomnia"],
 "Opioids slow the bowel, and tolerance to constipation does not develop; a stool softener and stimulant laxative are started with them."),
("After a mastectomy with lymph node removal, the patient should avoid which on the affected arm?",
 "Blood pressure readings", ["Hand exercises", "Raising it on pillows", "Gentle unscented lotion"],
 "Lymphedema risk rises after node removal, so blood pressures, injections and blood draws are avoided on that arm."),
("A patient with leukemia has bleeding gums and bruises. Which lab result explains this?",
 "Low platelet count", ["High hemoglobin", "Low serum potassium", "High glucose"],
 "Leukemic cells crowd out the marrow, so platelets fall and bleeding follows."),
]
